package com.nexushr.entity;
import jakarta.persistence.*; import java.time.*; import java.util.UUID; import java.math.BigDecimal;
@Entity @Table(name="employees") public class Employee { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @OneToOne(optional=false,cascade=CascadeType.ALL) @JoinColumn(name="user_id",unique=true) private User user; @Column(nullable=false) private String employeeCode; @Column(nullable=false) private String firstName; @Column(nullable=false) private String lastName; private String phone; private String department; private String designation; private String managerName; private LocalDate joiningDate; private LocalDate dateOfBirth; private String address; private String emergencyContact; @Column(precision=14,scale=2) private BigDecimal basicSalary=BigDecimal.ZERO; @Column(nullable=false) private boolean onboardingComplete=false; public UUID getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getEmployeeCode(){return employeeCode;} public void setEmployeeCode(String v){employeeCode=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getDesignation(){return designation;} public void setDesignation(String v){designation=v;} public String getManagerName(){return managerName;} public void setManagerName(String v){managerName=v;} public LocalDate getJoiningDate(){return joiningDate;} public void setJoiningDate(LocalDate v){joiningDate=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getEmergencyContact(){return emergencyContact;} public void setEmergencyContact(String v){emergencyContact=v;} public BigDecimal getBasicSalary(){return basicSalary;} public void setBasicSalary(BigDecimal v){basicSalary=v;} public boolean isOnboardingComplete(){return onboardingComplete;} public void setOnboardingComplete(boolean v){onboardingComplete=v;} }
